<script lang="ts">
  import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getComboboxContext, ComboboxItemState, setComboboxItemContext } from './combobox-context.svelte.js';
  interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; value: unknown; label?: string; disabled?: boolean; ref?: HTMLDivElement | null; }
  let { children, value, label, disabled = false, ref = $bindable(null), onpointerdown, onclick, onpointermove, ...rest }: Props = $props(); const uid = $props.id(); const box = getComboboxContext(); const item = setComboboxItemContext(new ComboboxItemState()); $effect.pre(() => { item.id = uid; item.value = value; item.label = label ?? box.itemToString(value); item.disabled = disabled; item.element = ref; }); $effect(() => { if (ref) return box.register(item); }); let selected = $derived(box.isSelected(value)); let highlighted = $derived(box.highlightedId === uid); let visible = $derived(box.filter(value, box.inputValue));
</script>
{#if visible}<div bind:this={ref} {...rest} id={uid} role="option" tabindex="-1" aria-selected={selected} aria-disabled={disabled || undefined} data-selected={selected ? '' : undefined} data-highlighted={highlighted ? '' : undefined} data-disabled={disabled ? '' : undefined} onpointerdown={composeEventHandlers(onpointerdown, (event) => event.preventDefault())} onclick={composeEventHandlers(onclick, (event) => { if (!disabled) { box.select(value, 'item-press', event); box.input?.focus(); } })} onpointermove={composeEventHandlers(onpointermove, () => { if (!disabled) box.highlightedId = uid; })}>{@render children?.()}</div>{/if}
